1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	// Every step so far is a quote and carries items. When claim steps arrive they
9	// will likely make this a union on `op` rather than an optional `items`.
10	export type Step = {
11	  op: string;
12	  items: Item[];
13	};
14	
15	export type Customer = { yearsWithMHPCO: number };
16	
17	export type Scenario = {
18	  customer: Customer;
19	  steps: Step[];
20	};
21	
22	export type StepResult = { premium: number };
23	
24	export type ScenarioResult = { results: StepResult[] };
25	
26	const BASE_PRICE_BY_TYPE: Record<string, number> = {
27	  sword: 100,
28	  amulet: 60,
29	  staff: 80,
30	  potion: 40,
31	  rune: 25,
32	  moonstone: 25,
33	};
34	
35	const FIRST_INSURANCE_MULTIPLIER = 1.1;
36	const CONTRACT_FEE = 5;
37	
38	const BUILDING_BLOCK_SIZE = 3;
39	const BUILDING_BLOCK_PRICE = 60;
40	
41	const CURSED_SURCHARGE_RATE = 0.5;
42	const HIGH_ENCHANTMENT_LEVEL = 5;
43	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
44	
45	// Each surcharge adds a percentage of the base price when its condition holds.
46	// Rates add together, so a cursed and highly enchanted item pays 1 + 0.5 + 0.3.
47	const RISK_SURCHARGES: { appliesTo: (item: Item) => boolean; rate: number }[] = [
48	  { appliesTo: (item) => item.cursed === true, rate: CURSED_SURCHARGE_RATE },
49	  {
50	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
51	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
52	  },
53	];
54	
55	const totalSurchargeRateFor = (item: Item): number =>
56	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
57	    (total, surcharge) => total + surcharge.rate,
58	    0,
59	  );
60	
61	// Risk surcharges apply per item, before the contract-level multiplier and fee.
62	const riskAdjustedPriceOfItem = (item: Item): number =>
63	  BASE_PRICE_BY_TYPE[item.type] * (1 + totalSurchargeRateFor(item));
64	
65	const sumOfIndividualPrices = (items: Item[]): number =>
66	  items.reduce((total, item) => total + riskAdjustedPriceOfItem(item), 0);
67	
68	// "Alike" in the price list means same type — material and enchantment do not
69	// affect whether components group into a building block.
70	const groupByType = (items: Item[]): Item[][] => {
71	  const groups = new Map<string, Item[]>();
72	
73	  for (const item of items) {
74	    const group = groups.get(item.type) ?? [];
75	    group.push(item);
76	    groups.set(item.type, group);
77	  }
78	
79	  return [...groups.values()];
80	};
81	
82	// Every three alike components form a building block priced at 60 G; the
83	// remainder of the group is priced individually.
84	const priceOfAlikeGroup = (group: Item[]): number => {
85	  const blocks = Math.floor(group.length / BUILDING_BLOCK_SIZE);
86	  const leftovers = group.slice(blocks * BUILDING_BLOCK_SIZE);
87	
88	  return blocks * BUILDING_BLOCK_PRICE + sumOfIndividualPrices(leftovers);
89	};
90	
91	// The insured value of the whole list: price-list figures plus per-item risk
92	// surcharges, before any contract-level multiplier or fee.
93	const insuredValueOf = (items: Item[]): number =>
94	  groupByType(items).reduce((total, group) => total + priceOfAlikeGroup(group), 0);
95	
96	const LOYALTY_YEARS = 2;
97	const LOYALTY_DISCOUNT_RATE = 0.2;
98	
99	const loyaltyMultiplierFor = (customer: Customer): number =>
100	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? 1 - LOYALTY_DISCOUNT_RATE : 1;
101	
102	const REPEAT_CONTRACT_DISCOUNT_RATE = 0.15;
103	
104	// A first insurance carries an assessment surcharge; every later contract
105	// earns the repeat-customer discount instead.
106	const repeatCustomerMultiplierFor = (precedingContracts: number): number =>
107	  precedingContracts === 0
108	    ? FIRST_INSURANCE_MULTIPLIER
109	    : 1 - REPEAT_CONTRACT_DISCOUNT_RATE;
110	
111	// Customer-dependent factors that scale the whole contract, as opposed to the
112	// per-item risk surcharges already folded into the insured value.
113	const contractMultiplierFor = (
114	  customer: Customer,
115	  precedingContracts: number,
116	): number =>
117	  loyaltyMultiplierFor(customer) * repeatCustomerMultiplierFor(precedingContracts);
118	
119	// Amounts are rounded up, in MHPCO's favor. The product is first snapped to
120	// six decimals so IEEE754 noise (100 × 1.1 = 110.00000000000001) does not
121	// push an exact amount to the next whole G.
122	const roundedUpInMHPCOsFavor = (amount: number): number =>
123	  Math.ceil(Number(amount.toFixed(6)));
124	
125	const quoteStep = (
126	  step: Step,
127	  customer: Customer,
128	  precedingContracts: number,
129	): StepResult => ({
130	  premium:
131	    roundedUpInMHPCOsFavor(
132	      insuredValueOf(step.items) *
133	        contractMultiplierFor(customer, precedingContracts),
134	    ) + CONTRACT_FEE,
135	});
136	
137	export const runScenario = (scenario: Scenario): ScenarioResult => ({
138	  results: scenario.steps.map((step, index) =>
139	    quoteStep(step, scenario.customer, index),
140	  ),
141	});
